comments.suggestion_code:
interface GitModule { run(args: string[]): unknown; }
const mod: GitModule = await import(spec);
if (typeof mod.run !== "function") {
  process.stderr.write(`${action}: module ${spec} exports no run(args)\n`);
  process.exit(1);
}
await mod.run(args);

